entries[435958] = { ["name"] = "Whirling Truesilver Gearwall", ["text"] = "45 sec cast\nTools: Blacksmith Hammer\nReagents:\nLow-Background Truesilver Plates (3), Polished Truesilver Gears (5), Faintly Glowing Leather (2), Mithril Casing (2), Gyrochronatom (2), Mithril Bar (15)\nWhirling Truesilver Gearwall\nBinds when picked up\nOff Hand Shield\n1760 Armor\n29 Block\n+9 Strength\n+10 Stamina\nDurability 120 / 120\n40\nRequires Engineering\n(225)\nEquip: Increases your chance to block attacks with a shield by 1%.\nEquip: On a successful block the whirling razor-sharp gears on this shield inflict 5 to 10 physical damage to the attacker and 2 to 10 physical damage to the bearer.\n\"The rotating edges on this shield are surprisingly sharp. This seems just as dangerous for the bearer as it is to the attacker.\"" }
entries[435959] = { ["name"] = "Schematic: Whirling Truesilver Gearwall", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make a Whirling Truesilver Gearwall." }
entries[435960] = { ["name"] = "Hyperconductive Goldwap", ["text"] = "45 sec cast\nTools: Arclight Spanner\nReagents:\nPolished Truesilver Gears (3), Hyperconductive Arcano-Filament (3), Faintly Glowing Leather , Gold Bar (10)\nHyperconductive Goldwrap\nBinds when picked up\nWaist Cloth\n40 Armor\n+9 Stamina\nDurability 35 / 35\n40\nRequires Engineering\n(225)\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nUse: Pull a hyperconductive coin from your belt and flip it. Heads: gain 3% increased critical strike chance with all spells and attacks for 30 sec. Tails: gain 10% movement speed for 30 sec. (15 Min Cooldown)\n\"This belt clinks faintly as you move.\"" }
entries[435961] = { ["name"] = "Schematic: Hyperconductive Goldwap", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make a Hyperconductive Goldwap" }
